-- 314_hsfc_gapfund_seeds.sql
-- HSFC (北海道スタートアップ・エコシステム推進協議会) GAPファンド 2021-2025年度 採択課題を seeds へ投入する。
-- 出典: HSFC 公開の採択課題一覧 PDF (4年度分 計86件)。同一研究者・同一テーマの重複を統合し、
-- 既に seeds にある2件 (矢口裕章 / 鳥屋尾隆) を除いた新規 68 件。
-- 運用規律: 一次ソースURL・連絡先・個人情報・secret は保存しない。
-- 採択年度・枠は PDF の記載どおり。金額は枠の上限額が明記されているものだけ入れ、
-- 記載のない枠は NULL のままにする (実交付額は非公表)。
BEGIN;

WITH src (title, summary, org_name, org_region, researcher_name, researcher_title,
          domain_lane, industry_target, keywords, status, source_detail) AS (
  VALUES
    ('耐放射線ダイヤモンド半導体デバイス','放射線に耐えるダイヤモンド半導体デバイスと、それを使った電子機器の試作・評価。原子力・宇宙など高放射線環境向けのパワー半導体。2022年3月に大熊ダイヤモンドデバイス株式会社として法人化済み。','北海道大学','北海道札幌市','星川 尚久','学術研究員','materials',ARRAY['半導体','原子力','宇宙']::text[],ARRAY['ダイヤモンド半導体','耐放射線','パワーデバイス','HSFC']::text[],'spun_off','HSFC GAPファンド 2021年度 採択 (北海道大学)'),
    ('メカノケミカル有機合成の実用化','溶媒を使わず機械的な力で有機合成を進めるメカノケミカル法の実用化。化学産業の脱溶媒・省エネ化を狙う。2023年11月に株式会社メカノクロスとして法人化済み。2021年度と2022年度ビジネスチャレンジ枠に連続採択。','北海道大学','北海道札幌市','伊藤 肇','教授','materials',ARRAY['化学','医薬中間体','GX']::text[],ARRAY['メカノケミカル','無溶媒合成','有機合成','HSFC']::text[],'spun_off','HSFC GAPファンド 2021年度 採択 (北海道大学)'),
    ('抗原検査を高感度化するウイルス捕捉・濃縮材料','抗原検査の判定精度を高めるウイルス捕捉材料の開発。2022年度はウイルス濃縮材料と生産技術の構築へ発展。感染症の迅速診断の感度を材料側から底上げする。','苫小牧工業高等専門学校','北海道苫小牧市','甲野 裕之','教授','life',ARRAY['体外診断','感染症']::text[],ARRAY['抗原検査','ウイルス捕捉','濃縮材料','HSFC']::text[],'investigating','HSFC GAPファンド 2021年度 採択 (苫小牧工業高等専門学校)'),
    ('Cancer-on-chip デバイスによる癌腫瘍組織モデル','マイクロデバイス上に癌腫瘍組織を再現する Cancer-on-chip の開発と、創薬スクリーニングへの応用検証。動物実験に依らない薬効評価系を目指す。','北海道大学','北海道札幌市','繁富 香織','特任准教授','life',ARRAY['創薬支援','がん']::text[],ARRAY['Cancer-on-chip','腫瘍モデル','創薬スクリーニング','HSFC']::text[],'investigating','HSFC GAPファンド 2021年度 採択 (北海道大学)'),
    ('食用タンパク源ウキクサ Wolffia のオンデマンド生産技術','持続可能な食用タンパク源としてウキクサ属 Wolffia を必要量だけ生産する技術の開発。代替タンパク質の国内生産を狙う。2023年5月に Floatmeal 株式会社として法人化済み。','北海道大学','北海道札幌市','カマルシュブロ サジャッド','博士後期課程2年','life',ARRAY['代替タンパク質','食品','農業']::text[],ARRAY['ウキクサ','Wolffia','代替タンパク質','植物工場','HSFC']::text[],'spun_off','HSFC GAPファンド 2021年度 採択 (北海道大学)'),
    ('人工エクソソーム医薬品の製造技術','人工エクソソームを医薬品として製造する技術の開発と事業化検証。細胞外小胞を用いたドラッグデリバリーの製造プロセス側を担う。','北海道大学','北海道札幌市','真栄城 正寿','准教授','life',ARRAY['バイオ医薬','DDS']::text[],ARRAY['人工エクソソーム','細胞外小胞','DDS','製造技術','HSFC']::text[],'investigating','HSFC GAPファンド 2021年度 採択 (北海道大学)'),
    ('魚介類の鮮度可視化管理システム','魚介類の鮮度を可視化して管理するシステムのユーザインターフェース開発。水産流通の品質管理をデータ化する。','北海道大学','北海道札幌市','坪内 直人','准教授','ict',ARRAY['水産','食品流通']::text[],ARRAY['鮮度可視化','水産流通','品質管理','HSFC']::text[],'investigating','HSFC GAPファンド 2021年度 採択 (北海道大学)'),
    ('タンパク質医薬の化学修飾ライブラリー・修飾プラットフォーム','タンパク質ドラッグに新たな化学修飾部位を付与するリポジショニング・ライブラリーの構築。2022年度はN末端修飾技術を基盤とした診断薬・バイオ医薬品の製造、2025年度はタンパク質と修飾剤を最適に繋ぐプラットフォームへ発展。3年度にわたり連続採択。','北海道大学','北海道札幌市','小野田 晃','教授','life',ARRAY['バイオ医薬','診断薬']::text[],ARRAY['タンパク質修飾','N末端修飾','抗体薬物複合体','HSFC']::text[],'investigating','HSFC GAPファンド 2021年度 採択 (北海道大学)'),
    ('TlBr 半導体γ線センサーの製造・販売','医療診断装置への応用を目指した臭化タリウム (TlBr) 半導体γ線センサーの開発。2021年度・2022年度ビジネスチャレンジ枠を経て、2024年度は STEP2 スタートアップ組成枠に採択され製造・販売段階の検討に入っている。','北海道大学','北海道札幌市','金子 純一','准教授','materials',ARRAY['医療機器','放射線計測']::text[],ARRAY['TlBr','臭化タリウム','γ線センサー','核医学','HSFC']::text[],'investigating','HSFC GAPファンド 2021年度 採択 (北海道大学)'),
    ('オール多糖ガス分離膜','多糖のみで構成するガス分離膜の開発。カーボンニュートラルに向けた分離プロセスの省エネ化を狙う。小樽商科大学・北海道大学・苫小牧工業高等専門学校の3機関共同。','小樽商科大学','北海道小樽市','沼田 ゆかり','教授','materials',ARRAY['ガス分離','GX','化学プロセス']::text[],ARRAY['多糖','ガス分離膜','カーボンニュートラル','HSFC']::text[],'investigating','HSFC GAPファンド 2021年度 採択 (小樽商科大学)'),
    ('食品用液体急速凍結-解凍システム','北海道産食品向けの液体急速凍結と解凍を組み合わせたシステムの開発。凍結時の品質劣化を抑えて食品の付加価値を保つ。','室蘭工業大学','北海道室蘭市','関 千草','助教','other',ARRAY['食品加工','食品機械']::text[],ARRAY['急速凍結','液体凍結','食品加工','HSFC']::text[],'investigating','HSFC GAPファンド 2021年度 採択 (室蘭工業大学)'),
    ('腰部負担可視化デバイスによる作業負担評価','装着型デバイスで腰部への負担を可視化し、作業負担を評価するシステムの開発。労働災害予防と作業設計の改善に使う。','苫小牧工業高等専門学校','北海道苫小牧市','土谷 圭央','助教','robo',ARRAY['労働安全','ウェアラブル']::text[],ARRAY['腰部負担','ウェアラブルセンサ','作業負担評価','HSFC']::text[],'investigating','HSFC GAPファンド 2021年度 採択 (苫小牧工業高等専門学校)'),
    ('保健所の積極的疫学調査を支援するツール','保健所が行う積極的疫学調査を支援するツールの研究開発。感染症対応の現場業務をデジタル化する。','北海道大学','北海道札幌市','坂本 大介','准教授','ict',ARRAY['公衆衛生','自治体DX']::text[],ARRAY['疫学調査','保健所','感染症対応','HSFC']::text[],'investigating','HSFC GAPファンド 2021年度 採択 (北海道大学)'),
    ('1粒子解析によるリキッドバイオプシーがん診断','体液検査によるがん診断システムの開発。2024年度は1粒子解析技術を用いたバイオデバイスの実装として STEP2 スタートアップ組成枠に採択。血液・体液から粒子単位でがんを検出する。','北海道大学','北海道札幌市','龍崎 奏','准教授','life',ARRAY['体外診断','がん']::text[],ARRAY['リキッドバイオプシー','1粒子解析','がん診断','細胞外小胞','HSFC']::text[],'investigating','HSFC GAPファンド 2022年度 ビジネスチャレンジ枠 採択 (北海道大学)'),
    ('新型省電力集積回路','消費電力を大きく下げる新型の集積回路の開発。半導体ナノ構造を用いたデバイス設計を基盤とする。','北海道大学','北海道札幌市','冨岡 克広','准教授','materials',ARRAY['半導体','省エネ']::text[],ARRAY['集積回路','省電力','ナノワイヤ','HSFC']::text[],'investigating','HSFC GAPファンド 2022年度 DeepTech枠 採択 (北海道大学)'),
    ('世界最高解像度の3Dバイオイメージング技術','生体試料を三次元で高解像度に観察するバイオイメージング技術の開発と社会実装。研究用計測から診断応用までを視野に入れる。','北海道大学','北海道札幌市','伊庭 靖弘','准教授','life',ARRAY['研究用機器','診断']::text[],ARRAY['3Dイメージング','バイオイメージング','高解像度','HSFC']::text[],'investigating','HSFC GAPファンド 2022年度 DeepTech枠 採択 (北海道大学)'),
    ('免疫チェックポイント阻害剤の治療効果予測 (iCUREs)','免疫チェックポイント阻害剤によるがん治療の効果を事前に予測するサービス iCUREs の開発。2024年度は効果予測プラットフォームとして STEP2 スタートアップ組成枠に採択。高額薬剤の投与前選別で医療費と患者負担を下げる。','北海道大学','北海道札幌市','小林 弘一','教授','life',ARRAY['がん','コンパニオン診断']::text[],ARRAY['免疫チェックポイント阻害剤','効果予測','コンパニオン診断','HSFC']::text[],'investigating','HSFC GAPファンド 2022年度 DeepTech枠 採択 (北海道大学)'),
    ('フロー精密重合による高分子材料の連続生産','アニオン重合の実用化を志向したフロー精密重合の実証。2024年度は高度に構造を制御した人工高分子材料の生産事業として STEP1 に採択。分子量・構造を精密に制御した高分子を連続生産する。','北海道大学','北海道札幌市','芦刈 洋祐','特任助教','materials',ARRAY['高分子','化学']::text[],ARRAY['アニオン重合','フロー精密重合','精密高分子','HSFC']::text[],'investigating','HSFC GAPファンド 2022年度 DeepTech枠 採択 (北海道大学)'),
    ('エチレン徐放固体材料による農作物の生長・熟成制御','植物ホルモンであるエチレンを徐放する固体材料の開発。農作物の生長度・熟成度を制御し、収穫・流通のタイミングを合わせる。','北海道大学','北海道札幌市','野呂 真一郎','教授','materials',ARRAY['農業資材','食品流通']::text[],ARRAY['エチレン','徐放材料','多孔性材料','熟成制御','HSFC']::text[],'investigating','HSFC GAPファンド 2022年度 DeepTech枠 採択 (北海道大学)'),
    ('IoT向け電力自給技術 (環境発電)','サイバーフィジカルシステムの実現に向けた IoT 機器向けの電力自給技術。電池交換の要らないセンサ網を狙う。','函館工業高等専門学校','北海道函館市','中津川 征士','教授','gx_energy',ARRAY['IoT','環境発電']::text[],ARRAY['エネルギーハーベスティング','IoT','電力自給','HSFC']::text[],'investigating','HSFC GAPファンド 2022年度 DeepTech枠 採択 (函館工業高等専門学校)'),
    ('発芽制御ポリマーコート種子','秋播きを可能にする種子の多層ポリマーコーティングの開発。2024年度は「いつでも播種可能な発芽制御ができるポリマーコート種子」として STEP1 に採択。播種時期の制約を外して農作業の平準化を図る。','北見工業大学','北海道北見市','浪越 毅','准教授','materials',ARRAY['農業資材','高分子']::text[],ARRAY['種子コーティング','発芽制御','多層ポリマー','秋播き','HSFC']::text[],'investigating','HSFC GAPファンド 2022年度 研究成果実装・地域課題解決枠 採択 (北見工業大学)'),
    ('遺骨を土に還す樹木葬','遺骨を土に還す樹木葬の設計と運営。墓地の在り方と地域の緑地保全を結び付けるサービス。','北海道大学','北海道札幌市','上田 裕文','准教授','other',ARRAY['葬祭','地域']::text[],ARRAY['樹木葬','墓地','地域資源','HSFC']::text[],'investigating','HSFC GAPファンド 2022年度 研究成果実装・地域課題解決枠 採択 (北海道大学)'),
    ('ワイヤレス電力伝送応用マイクロ波融雷システム','ワイヤレス電力伝送を応用したマイクロ波システム。寒冷地インフラ向けの応用を検討する。','函館工業高等専門学校','北海道函館市','丸山 珠美','教授','gx_energy',ARRAY['寒冷地インフラ','無線電力伝送']::text[],ARRAY['ワイヤレス電力伝送','マイクロ波','寒冷地','HSFC']::text[],'investigating','HSFC GAPファンド 2022年度 研究成果実装・地域課題解決枠 採択 (函館工業高等専門学校)'),
    ('DX人材ネットワークによる地域課題のデータ分析','DX人材のネットワークを組織し、地域課題のデータ分析と社会人向け教育・人材育成を行う。2023年2月に株式会社 en として法人化済み。','北海道大学','北海道札幌市','湧田 雄基','特任准教授','other',ARRAY['人材育成','地域DX']::text[],ARRAY['DX人材','データ分析','社会人教育','HSFC']::text[],'spun_off','HSFC GAPファンド 2022年度 研究成果実装・地域課題解決枠 採択 (北海道大学)'),
    ('科学とアートによる人-環境相互課題の人材育成プログラム','科学とアートを組み合わせて人と環境の相互課題を解決する人材を育てるプログラムの開発と実装。','北海道大学','北海道札幌市','渡邊 剛','講師','other',ARRAY['教育','環境']::text[],ARRAY['科学とアート','人材育成','環境教育','HSFC']::text[],'investigating','HSFC GAPファンド 2022年度 研究成果実装・地域課題解決枠 採択 (北海道大学)'),
    ('サイエンスコミュニケーションによる社会との共創の場','サイエンスコミュニケーションを通じて研究と社会が共創する場をつくる事業。2023年5月に株式会社サイバコとして法人化済み。','北海道大学','北海道札幌市','奥本 素子','准教授','other',ARRAY['科学コミュニケーション','教育']::text[],ARRAY['サイエンスコミュニケーション','共創','対話の場','HSFC']::text[],'spun_off','HSFC GAPファンド 2022年度 研究成果実装・地域課題解決枠 採択 (北海道大学)'),
    ('植物の二次代謝物量をコントロールする技術','植物が作り出す二次代謝物の量を制御する方法の開発。2025年度は STEP2 スタートアップ組成枠へ進んでいる。機能性成分や薬用成分の含有量を狙って調整する。','北見工業大学','北海道北見市','陽川 憲','准教授','life',ARRAY['農業','機能性食品','植物由来原料']::text[],ARRAY['二次代謝物','植物工場','機能性成分','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北見工業大学)'),
    ('自律浮沈式の水浄化材','自ら浮き沈みする水浄化材の開発と性能評価。電源やポンプの要らない水処理として、グローバルサウスでの上下水インフラが乏しい地域を想定している。','北海道科学大学','北海道札幌市','三原 義広','講師','gx_circular',ARRAY['水処理','新興国インフラ']::text[],ARRAY['水浄化材','自律浮沈','無電源水処理','グローバルサウス','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北海道科学大学)'),
    ('がん幹細胞誘導ゲルと専用培養ディッシュ','がん幹細胞を誘導するハイドロゲル (HARP誘導ゲル) と専用培養ディッシュ。2025年度は STEP2 で、がん幹細胞を高含有したスフェロイドと PDX マウスの提供サービス事業化へ進んでいる。創薬スクリーニングの前臨床モデルを供給する。','北海道大学','北海道札幌市','黒川 孝幸','教授','life',ARRAY['創薬支援','がん']::text[],ARRAY['がん幹細胞','ハイドロゲル','スフェロイド','PDXマウス','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北海道大学)'),
    ('データセットなしで作物と雑草を識別するアプリ','事前の学習データセットを用意せずに作物と雑草を識別するアプリケーションの開発。ピンポイント除草や農作業の自動化に使う。','北海道大学','北海道札幌市','井内 悠介','博士課程2年','ict',ARRAY['スマート農業']::text[],ARRAY['雑草識別','画像認識','スマート農業','少数データ学習','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北海道大学)'),
    ('超高感度光学式マイクロ熱量計','光学式の超高感度マイクロ熱量計の開発と、創薬結晶工学への応用。微量サンプルの熱測定で結晶多形の探索を効率化する。','苫小牧工業高等専門学校','北海道苫小牧市','渡邉 智','准教授','materials',ARRAY['分析機器','創薬支援']::text[],ARRAY['マイクロ熱量計','光学計測','結晶工学','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (苫小牧工業高等専門学校)'),
    ('産業用バイオナノファイバーの生産プロセスと繊維材料','バイオナノファイバーの産業用生産プロセスと、それを使った繊維材料の開発。石油由来素材の置き換えを狙う。','北海道大学','北海道札幌市','高濱 良','博士研究員','materials',ARRAY['繊維','バイオマス素材']::text[],ARRAY['バイオナノファイバー','セルロースナノファイバー','繊維材料','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北海道大学)'),
    ('経内視鏡で使える医療用ハイドロゲル','内視鏡を通して使用できる医療用ハイドロゲルの開発。消化管の粘膜下注入や止血・被覆材としての応用を想定する。','北海道大学','北海道札幌市','大野 正芳','特任助教','life',ARRAY['医療機器','消化器']::text[],ARRAY['ハイドロゲル','内視鏡','医療材料','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北海道大学)'),
    ('アルカリ膜水電解によるアドオン型重水製造装置','アルカリ膜水電解を用いて既存設備に後付けできる重水製造装置の開発。重水は原子力・半導体・医療分野で使われる高付加価値材料。','北海道大学','北海道札幌市','佐藤 衣吹','修士課程2年','gx_energy',ARRAY['水電解','素材','原子力']::text[],ARRAY['アルカリ膜水電解','重水','水素','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北海道大学)'),
    ('アニサキス症を自己防衛できる経口摂取物','生魚を食べる消費者がアニサキス症の発症を自分で防げる経口摂取物の開発。食品・サプリメント形態での提供を想定する。','北海道科学大学','北海道札幌市','丁野 純男','教授','life',ARRAY['食品','健康','水産']::text[],ARRAY['アニサキス','食中毒予防','経口摂取物','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北海道科学大学)'),
    ('牛ふんメタン発酵消化液を用いた拡散駆動型微細藻類培養','家畜ふん尿のメタン発酵消化液を栄養源にした拡散駆動型の微細藻類培養技術。2025年度は健全な窒素循環のための生産技術として STEP2 に進んでいる。畜産廃棄物を藻類バイオマスへ変える。','北海道大学','北海道札幌市','石井 一英','教授','gx_circular',ARRAY['畜産','バイオマス','窒素循環']::text[],ARRAY['メタン発酵消化液','微細藻類','窒素循環','畜産廃棄物','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北海道大学)'),
    ('省人型の自動フロー合成システム','研究開発を省人化する自動フロー合成システムの開発。2025年度は「フローマイクロ法による化学産業の革新」として STEP2 に進んでいる。バッチ合成をフロー化して連続生産と自動化を同時に実現する。','北海道大学','北海道札幌市','永木 愛一郎','教授','materials',ARRAY['化学','医薬中間体','研究機器']::text[],ARRAY['フロー合成','フローマイクロ','自動合成','省人化','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北海道大学)'),
    ('三次元水位差灌流細胞培養法','水位差を利用して三次元の細胞組織へ灌流する培養法の開発と応用展開。ポンプに依らない灌流培養で組織モデルを維持する。','北海道大学','北海道札幌市','石原 誠一郎','助教','life',ARRAY['細胞培養','創薬支援','再生医療']::text[],ARRAY['三次元培養','灌流培養','水位差','オルガノイド','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北海道大学)'),
    ('新規鉱山の選鉱プロセス設計支援 機械学習モデル','新規鉱山の選鉱プロセス設計を支援する機械学習モデルの開発。2025年度は選鉱プロセスの設計・評価・最適化支援として STEP2 に進んでいる。資源開発の初期設計を短縮する。','北海道大学','北海道札幌市','廣吉 直樹','教授','gx_circular',ARRAY['資源開発','鉱業','素材']::text[],ARRAY['選鉱','鉱山','機械学習','プロセス設計','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北海道大学)'),
    ('遺伝子発現抑制配列の破壊による有用作物品種開発','遺伝子発現を抑制している配列を壊すことで有用な作物品種を作る技術。ゲノム編集による育種の高速化を狙う。','北海道大学','北海道札幌市','尾之内 均','教授','life',ARRAY['育種','農業']::text[],ARRAY['ゲノム編集','遺伝子発現制御','育種','作物品種','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北海道大学)'),
    ('白金フリーの高耐久・低コスト燃料電池触媒','水素利用のための白金を使わない高耐久・低コスト触媒の事業化。2025年度は災害レジリエンスと水素社会を支える燃料電池触媒として STEP2 に進んでいる。白金の資源制約と価格変動を外す。','北海道大学','北海道札幌市','武安 光太郎','准教授','gx_energy',ARRAY['燃料電池','水素','GX']::text[],ARRAY['白金フリー','燃料電池触媒','水素','レアメタル代替','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北海道大学)'),
    ('力覚を持つ作業教示可能な汎用ロボット (水産業向け)','力覚を備え、誰でも作業を教示できる汎用ロボットの開発と水産業への適用。熟練者の手作業をロボットへ移す。','北海道大学','北海道札幌市','牧 駿','博士課程1年','robo',ARRAY['ロボット','水産','食品加工']::text[],ARRAY['力覚','作業教示','汎用ロボット','水産業','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP1 プレ支援枠 採択 (北海道大学)'),
    ('超高密度蓄熱材によるグリーンヒート供給','超高密度の蓄熱材を用いて熱を貯蔵・輸送し、産業用熱の脱炭素化を進める事業。2024年度 STEP2 スタートアップ組成枠に採択。工場の燃焼由来熱を再エネ由来の熱へ置き換える。','北海道大学','北海道札幌市','能村 貴宏','教授','gx_energy',ARRAY['産業用熱','蓄熱','GX']::text[],ARRAY['蓄熱材','グリーンヒート','熱の脱炭素化','産業炉','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP2 スタートアップ組成枠 採択 (北海道大学)'),
    ('高齢心不全患者のフレイル自動判定プログラム','高齢の心不全患者のフレイル (虚弱) を自動で判定するプログラムの開発と実装。2024年度 STEP2 スタートアップ組成枠に採択。循環器領域の予後予測と介入判断を支援する。','北海道大学','北海道札幌市','永井 利幸','准教授 (診療教授)','life',ARRAY['医療ソフトウェア','循環器','高齢者医療']::text[],ARRAY['フレイル','心不全','自動判定','SaMD','HSFC']::text[],'investigating','HSFC GAPファンド 2024年度 STEP2 スタートアップ組成枠 採択 (北海道大学)'),
    ('既設コンクリートを大気CO2吸収体に変えるDACコート','既存のコンクリート構造物の表面に塗ることで、森林より高効率に大気中のCO2を吸収させるコート材の開発と社会実装。既設インフラをそのままCO2除去装置として使う。','北海道大学','北海道札幌市','北垣 亮馬','教授','gx_circular',ARRAY['CO2除去','建設','インフラ']::text[],ARRAY['DAC','直接空気回収','コンクリート','炭酸化','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (北海道大学)'),
    ('物語構造分析に基づく創作支援システム','物語の構造分析をもとに、コンテンツ制作者向けの物語創作支援システムを開発する。作劇のパターンを解析して構成案を提示する。','公立はこだて未来大学','北海道函館市','村井 源','教授','ict',ARRAY['コンテンツ制作','出版','映像']::text[],ARRAY['物語構造','創作支援','計算文学','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (公立はこだて未来大学)'),
    ('スマホ連携型ポータブル水質細菌検査キット','スマートフォンと連携する持ち運び可能な水質セーフティ細菌検査キットの開発。現場で飲料水の細菌汚染を判定する。','北海道大学','北海道札幌市','佐藤 久','教授','gx_circular',ARRAY['水質検査','上下水道','新興国インフラ']::text[],ARRAY['水質検査','細菌検査','スマホ連携','現場診断','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (北海道大学)'),
    ('粉体物理に基づく微粒子選別システム','粉体の物理特性を利用した革新的な微粒子選別システムの開発。粒径や形状ではなく物性の違いで分ける。','北海道大学','北海道札幌市','原田 周作','准教授','materials',ARRAY['粉体プロセス','資源リサイクル','素材']::text[],ARRAY['粉体','微粒子選別','分級','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (北海道大学)'),
    ('レーザ援用超音波探傷による遠隔インフラ診断','レーザで超音波を発生・受信し、非接触で構造物を探傷イメージングする遠隔インフラ診断技術。橋梁や配管に触れずに内部欠陥を可視化する。','室蘭工業大学','北海道室蘭市','荘司 成熙','助教','robo',ARRAY['インフラ点検','計測機器','プラント保全']::text[],ARRAY['レーザ超音波','非破壊検査','探傷イメージング','遠隔診断','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (室蘭工業大学)'),
    ('心臓外科手術支援に特化したAIプラットフォーム','心臓外科手術の支援に特化したAIプラットフォームの開発。術中判断や術式選択の支援を狙う。','公立はこだて未来大学','北海道函館市','佐藤 生馬','教授','life',ARRAY['医療ソフトウェア','外科','循環器']::text[],ARRAY['手術支援AI','心臓外科','SaMD','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (公立はこだて未来大学)'),
    ('個別化がんワクチン設計AIプラットフォーム','患者ごとのがんワクチンを設計するAIプラットフォームの開発と事業化。腫瘍の変異情報から免疫が反応する抗原を選ぶ。','札幌医科大学','北海道札幌市','鳥越 俊彦','訪問研究員','life',ARRAY['がん免疫','創薬','医療AI']::text[],ARRAY['がんワクチン','ネオアンチゲン','個別化医療','創薬AI','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (札幌医科大学)'),
    ('微生物プロセス用の高性能合成培地','CMO/CDMO 向けの微生物プロセス用高性能合成培地の開発と事業化可能性の検証。バイオ生産の培地を組成が明確な合成品へ置き換える。','北見工業大学','北海道北見市','小西 正朗','教授','life',ARRAY['バイオ生産','培地','CDMO']::text[],ARRAY['合成培地','微生物','バイオプロセス','CDMO','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (北見工業大学)'),
    ('ゼラチンハイドロゲル粒子型MSCによる消化管局所療法','難治性の消化管病変に対し、ゼラチンハイドロゲル粒子に間葉系幹細胞 (MSC) を担持した局所療法の技術開発と事業化検討。局所に細胞を留めて効かせる。','札幌医科大学','北海道札幌市','永石 歓和','教授','life',ARRAY['再生医療','消化器']::text[],ARRAY['間葉系幹細胞','ゼラチンハイドロゲル','局所投与','消化管','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (札幌医科大学)'),
    ('社会的ひきこもりの予防法・早期支援法','社会的ひきこもりを生物・心理・社会の三側面から捉えるモデルに基づく予防法と早期支援法の開発。','北海道大学','北海道札幌市','加藤 隆弘','教授','life',ARRAY['メンタルヘルス','公衆衛生']::text[],ARRAY['ひきこもり','生物心理社会モデル','早期支援','メンタルヘルス','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (北海道大学)'),
    ('レザバーコンピューティングによる筋電義手制御','レザバーコンピューティングを用い、指の角度と関節トルクを推定できる筋電義手の制御システムを開発する。少ない計算資源で滑らかな多指制御を狙う。','公立はこだて未来大学','北海道函館市','櫻沢 繁','教授','robo',ARRAY['義肢装具','医療機器','ロボット']::text[],ARRAY['筋電義手','レザバーコンピューティング','関節トルク推定','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (公立はこだて未来大学)'),
    ('鉱山のネガティブアセットをCO2除去工場へ','鉱山開発が残した負の資産 (廃石・尾鉱など) を、CO2を鉱物固定する除去装置として使う構想。廃棄物の処理コストをCO2除去の価値へ転換する。','北海道大学','北海道札幌市','佐藤 遼弥','修士課程1年','gx_circular',ARRAY['CO2除去','鉱業','資源']::text[],ARRAY['鉱物固定','CO2除去','鉱山廃棄物','カーボンクレジット','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (北海道大学)'),
    ('省エネルギー脱硝を実現する低温作動触媒','低い温度で働く脱硝 (NOx除去) 触媒の開発。排ガス処理で必要だった再加熱を減らし、プラントや焼却炉の省エネルギー化につなげる。','北海道大学','北海道札幌市','村山 徹','教授','gx_energy',ARRAY['排ガス処理','プラント','自動車']::text[],ARRAY['脱硝','低温触媒','NOx','省エネ','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (北海道大学)'),
    ('小分子抗体DDSによる慢性腎臓病の創薬基盤','線維化した病巣に集積する小分子抗体をドラッグデリバリーに使い、慢性腎臓病を狙う創薬基盤。薬を効かせたい場所へ運ぶ。','北海道科学大学','北海道札幌市','戸上 紘平','准教授','life',ARRAY['創薬','腎疾患']::text[],ARRAY['小分子抗体','DDS','線維化','慢性腎臓病','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (北海道科学大学)'),
    ('細胞内代謝を標的とした自己免疫疾患治療薬','免疫細胞の細胞内代謝をターゲットにした自己免疫疾患の新規治療薬の開発。既存の免疫抑制とは別の作用点を狙う。','北海道大学','北海道札幌市','河野 通仁','准教授','life',ARRAY['創薬','自己免疫疾患','リウマチ']::text[],ARRAY['細胞内代謝','自己免疫疾患','免疫代謝','創薬','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (北海道大学)'),
    ('アミロイドPET定量化ソフト','認知症診断を支援するアミロイドPET画像の定量化ソフトウェアの開発。読影者による判定のばらつきを減らす。','北海道大学','北海道札幌市','平田 健司','准教授','life',ARRAY['医療ソフトウェア','認知症','画像診断']::text[],ARRAY['アミロイドPET','定量化','認知症診断','SaMD','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (北海道大学)'),
    ('脳卒中片麻痺者向け推進力アシストインソール','脳卒中による片麻痺のある人の歩行を、靴の中敷きで推進力を補助して支えるインソールの世界展開。装具より手軽に導入できる。','北海道科学大学','北海道札幌市','昆 恵介','教授','robo',ARRAY['義肢装具','リハビリ','ヘルスケア']::text[],ARRAY['インソール','片麻痺','歩行支援','義肢装具','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (北海道科学大学)'),
    ('EEM蛍光指紋法による下水水質分析','三次元蛍光スペクトル (EEM) の指紋パターンで下水水質を分析し、老朽下水管の調査を効率化する受託事業の開拓。管路の劣化箇所を水質から絞り込む。','北海道大学','北海道札幌市','中屋 佑紀','助教','gx_circular',ARRAY['下水インフラ','水質分析','自治体']::text[],ARRAY['EEM蛍光','水質分析','下水管','インフラ老朽化','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (北海道大学)'),
    ('携帯分光×AIによるオンサイト牧草・土壌診断','携帯型の分光計測とAIを組み合わせ、その場で牧草と土壌の状態を診断する技術。採土して分析機関へ送る流れを省く。','帯広畜産大学','北海道帯広市','翫 美里','博士前期課程1年','ict',ARRAY['畜産','スマート農業','計測機器']::text[],ARRAY['近赤外分光','牧草','土壌診断','オンサイト計測','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (帯広畜産大学)'),
    ('温度応答型の無電源遮光フィルム','温度に応じて自ら遮光の度合いが変わる、電源の要らないフィルムの開発と社会実装。施設園芸の遮光と建物の快適環境に使う。','室蘭工業大学','北海道室蘭市','馬渡 康輝','准教授','materials',ARRAY['施設園芸','建材','省エネ']::text[],ARRAY['温度応答','遮光フィルム','サーモクロミック','無電源','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (室蘭工業大学)'),
    ('転倒リスクタイプ別トレーニング提案システム','転倒のリスクを型で分類し、それぞれに合うトレーニングを提案するシステムの開発とエビデンス構築。介護予防の現場を想定する。','北海道科学大学','北海道札幌市','佐藤 洋一郎','教授','ict',ARRAY['介護予防','ヘルスケア','リハビリ']::text[],ARRAY['転倒リスク','介護予防','トレーニング提案','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP1 採択 (北海道科学大学)'),
    ('IL-6アンプ標的の非侵襲ニューロモデュレーション療法','難治性の間質性肺炎に対し、炎症増幅回路 (IL-6アンプ) を標的にした非侵襲の神経刺激療法を確立する。2025年度 STEP2 スタートアップ組成枠に採択。薬ではなく神経経由で炎症を抑える。','北海道大学','北海道札幌市','村上 正晃','教授','life',ARRAY['医療機器','呼吸器','炎症性疾患']::text[],ARRAY['IL-6アンプ','ニューロモデュレーション','間質性肺炎','非侵襲','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP2 採択 (北海道大学)'),
    ('ゼロショット樹冠検出','樹木の類似性と樹頂点の特徴を使い、学習データなしで樹冠を検出する技術。2025年度 STEP2 スタートアップ組成枠に採択。森林資源量の把握やカーボンクレジット算定に使う。','北海道大学','北海道札幌市','江丸 貴紀','准教授','ict',ARRAY['林業','森林計測','カーボンクレジット']::text[],ARRAY['樹冠検出','ゼロショット学習','リモートセンシング','森林資源','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP2 採択 (北海道大学)'),
    ('微生物セルロース由来のマイクロ繊維・シート材','微生物が作るセルロースを原料に、マイクロ繊維とシート材を開発する。2025年度 STEP2 スタートアップ組成枠に採択。石油由来素材や植物パルプの代替を狙う。','北海道大学','北海道札幌市','田島 健次','准教授','materials',ARRAY['繊維','バイオマス素材','包材']::text[],ARRAY['微生物セルロース','バクテリアセルロース','マイクロ繊維','シート材','HSFC']::text[],'investigating','HSFC GAPファンド 2025年度 STEP2 採択 (北海道大学)')
